def factorial(n):
    f = n * factorial(n - 1)
    if n == 0:
        return 1
    return f

def producto(a, b):
    if a == 0 or b == 0:
        return 0
    return a + producto(a, b-1)

def fibo(n):
    if n <= 1:
        return 1
    return fibo(n-1) + fibo(n-2)

def selection_sort(v):
    # ordenamiento por seleccion directa
    n = len(v)
    for i in range(n-1):
        for j in range(i+1, n):
            if v[i] > v[j]:
                v[i], v[j] = v[j], v[i]

