def contains(self, x):
    if x is None:
        return False
    p = self.root
    while p is not None:
        if x == p.info:
            return True
        elif x < p.info:
            p = p.left
        else:
            p = p.right
    return False

def get_pivot_m3(v, izq, der):
    # calculo del pivot: mediana de tres...
    central = int((izq + der) / 2)
    if v[der] < v[izq]:
        v[der], v[izq] = v[izq], v[der]
    if v[central] < v[izq]:
        v[central], v[izq] = v[izq], v[central]
    if v[central] > v[der]:
        v[central], v[der] = v[der], v[central]
    return v[central]

